-- AD4b CHECK (read-only): one row per rule, ok must be true on every row. Run through ad-sql-run.sh after AD04b.sql. D5a-4 lookup audit proof.
SELECT 'the five AD4b tables exist with RLS enabled and forced' AS rule, (SELECT count(*) FROM pg_class c JOIN pg_namespace s ON s.oid = c.relnamespace WHERE s.nspname = 'desk' AND c.relname IN ('fadm_lookup_link','fadm_lookup_cp','fadm_lookup_state','fadm_lookup_threshold','fadm_lookup_reason_block') AND c.relrowsecurity AND c.relforcerowsecurity) = 5 AS ok
UNION ALL SELECT 'links and checkpoints are append-only (update, delete, truncate triggers)', (SELECT count(*) FROM pg_trigger WHERE tgname IN ('fadm_lookup_link_frozen','fadm_lookup_link_frozen_t','fadm_lookup_cp_frozen','fadm_lookup_cp_frozen_t') AND NOT tgisinternal) = 4
UNION ALL SELECT 'every lookup insert gets its link (after-insert trigger)', EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = 'desk.fadm_lookup'::regclass AND tgname = 'fadm_lookup_90link')
UNION ALL SELECT 'a checkpoint takes size and root from the links (before-insert trigger) and is copied to the main ledger (after-insert trigger)', (SELECT count(*) FROM pg_trigger WHERE tgrelid = 'desk.fadm_lookup_cp'::regclass AND tgname IN ('fadm_lookup_cp_00before','fadm_lookup_cp_90after')) = 2
UNION ALL SELECT 'the fourth result abandoned is allowed by the outcome constraint', EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'desk.fadm_lookup'::regclass AND conname = 'fadm_lookup_outcome_ck' AND pg_get_constraintdef(oid) LIKE '%abandoned%')
UNION ALL SELECT 'the ten thresholds exist', (SELECT count(*) FROM desk.fadm_lookup_threshold) >= 10
UNION ALL SELECT 'four sensitive fields are marked', (SELECT count(*) FROM desk.fadm_lookup_field WHERE sensitive) = 4
UNION ALL SELECT 'the filler list has at least 40 words', (SELECT count(*) FROM desk.fadm_lookup_reason_block) >= 40
UNION ALL SELECT 'the new ledger kinds and the seal action exist', (SELECT count(*) FROM desk.fadm_ledger_kind WHERE kind IN ('lookup.history_read','lookup.person_read','lookup.proof_read','lookup.sealed','lookup.abandoned','lookup.threshold','lookup.verified','lookup.exported','lookup.export_mismatch')) = 9 AND EXISTS (SELECT 1 FROM desk.fadm_action WHERE action = 'audit.seal') AND EXISTS (SELECT 1 FROM desk.fadm_policy WHERE name = 'p_audit_seal')
UNION ALL SELECT 'Merkle known answer: root of three leaves is node(node(l0,l1),l2)', desk.fadm_merkle_mth(ARRAY[sha256('\x00'::bytea || sha256('a'::bytea)), sha256('\x00'::bytea || sha256('b'::bytea)), sha256('\x00'::bytea || sha256('c'::bytea))]) = sha256('\x01'::bytea || sha256('\x01'::bytea || sha256('\x00'::bytea || sha256('a'::bytea)) || sha256('\x00'::bytea || sha256('b'::bytea))) || sha256('\x00'::bytea || sha256('c'::bytea)))
UNION ALL SELECT 'Merkle proof verifier accepts a real path and refuses a wrong index', desk.fadm_merkle_verify(sha256('\x00'::bytea || sha256('c'::bytea)), 2, 3, ARRAY[sha256('\x01'::bytea || sha256('\x00'::bytea || sha256('a'::bytea)) || sha256('\x00'::bytea || sha256('b'::bytea)))],
    sha256('\x01'::bytea || sha256('\x01'::bytea || sha256('\x00'::bytea || sha256('a'::bytea)) || sha256('\x00'::bytea || sha256('b'::bytea))) || sha256('\x00'::bytea || sha256('c'::bytea))))
  AND NOT desk.fadm_merkle_verify(sha256('\x00'::bytea || sha256('c'::bytea)), 1, 3, ARRAY[sha256('x'::bytea)], sha256('y'::bytea))
UNION ALL SELECT 'every lookup row has its link and the whole chain verifies', desk.fadm_lookup_verify()
UNION ALL SELECT 'every checkpoint recomputes from the links and chains', desk.fadm_lookup_cp_verify()
UNION ALL SELECT 'desk_app has no right on the new tables', NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace s ON s.oid = c.relnamespace WHERE s.nspname = 'desk' AND c.relname IN ('fadm_lookup_link','fadm_lookup_cp','fadm_lookup_state','fadm_lookup_threshold','fadm_lookup_reason_block') AND (has_table_privilege('desk_app', c.oid, 'SELECT') OR has_table_privilege('desk_app', c.oid, 'INSERT') OR has_table_privilege('desk_app', c.oid, 'UPDATE') OR has_table_privilege('desk_app', c.oid, 'DELETE')))
UNION ALL SELECT 'the fourteen doors are granted to desk_app', (SELECT count(*) FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'desk' AND p.proname IN ('fadm_lookup_begin','fadm_lookup_finish','fadm_lookup_history','fadm_lookup_by_employee','fadm_lookup_seal','fadm_lookup_proof','fadm_lookup_verify_full','fadm_lookup_health','fadm_lookup_audit_door','fadm_lookup_cp_export','fadm_lookup_export_report','fadm_lookup_tick','fadm_lookup_threshold_set','fadm_merkle_verify') AND has_function_privilege('desk_app', p.oid, 'EXECUTE')) = 14
UNION ALL SELECT 'internal functions (maintain, signals, link_add, verify, root, leaves) are not granted to desk_app', NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'desk' AND p.proname IN ('fadm_lookup_maintain','fadm_lookup_signals','fadm_lookup_link_add','fadm_lookup_verify','fadm_lookup_verify_detail','fadm_lookup_root','fadm_lookup_leaves','fadm_lookup_cp_verify') AND has_function_privilege('desk_app', p.oid, 'EXECUTE'))
UNION ALL SELECT 'no PUBLIC execute on any lookup or merkle function', NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'desk' AND (p.proname LIKE 'fadm\_lookup%' OR p.proname LIKE 'fadm\_merkle%') AND has_function_privilege('public', p.oid, 'EXECUTE'))
UNION ALL SELECT 'all SECURITY DEFINER functions pin search_path', NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'desk' AND p.prosecdef AND (p.proconfig IS NULL OR NOT EXISTS (SELECT 1 FROM unnest(p.proconfig) c WHERE c LIKE 'search_path=%')))
UNION ALL SELECT 'reason quality: a real reason passes, filler fails', desk.fadm_lookup_reason_why('customer says mail is missing', false) IS NULL AND desk.fadm_lookup_reason_why('test test test test', false) IS NOT NULL AND desk.fadm_lookup_reason_why('just checking it now', false) IS NOT NULL
UNION ALL SELECT 'health door answers with counts only', (desk.fadm_lookup_health() ? 'tail_ok') AND (desk.fadm_lookup_health()::text !~* '(company|reason)')
UNION ALL SELECT 'the main ledger chain still verifies', desk.fadm_ledger_verify();
